#include <vector>
#include <array>
#include <algorithm>
#include <omp.h>

/*  Count how many values of x fall into each decile:
        [0,10), [10,20), … , [90,100]   (the value 100 is placed in the last bin)
    The result is stored in `bins`, which must contain exactly 10 elements.
    The computation is performed in parallel with OpenMP and is correct for
    any number of threads.
*/
void binsBy10Count(const std::vector<double>& x,
                   std::array<std::size_t, 10>& bins)
{
    // Initialise the output bins.
    bins.fill(0);

    // OpenMP reduction on an array slice (OpenMP 4.5+).  This guarantees that
    // each thread updates its private copy of the array and the private copies
    // are safely combined at the end of the parallel region.
    #pragma omp parallel for reduction(+:bins[:10]) schedule(static)
    for (std::size_t i = 0; i < x.size(); ++i) {
        // Determine the bin index.  Values exactly equal to 100 are placed
        // in the last bin (index 9).
        int idx = static_cast<int>(x[i] / 10.0);
        idx = std::min(idx, 9);          // clamp 100 → 9, also protects against overflow
        idx = std::max(idx, 0);          // protect against negative values (should not happen)

        bins[idx]++;                     // safe thanks to the reduction clause
    }
}
```

